{"code":"import json
import sys
import oracle


def main():
    with open(sys.argv[1], "r", encoding="utf-8") as f:
        data = json.load(f)

    ciphertext = bytes.fromhex(data["ciphertext_hex"])
    if len(ciphertext) != 32:
        raise ValueError("expected exactly two AES blocks")

    previous = ciphertext[:16]
    protected_length = int(data["protected_length"])
    if not 0 <= protected_length < 16:
        raise ValueError("invalid protected length")

    original_pad = 16 - protected_length
    intermediate = [None] * 16

    for i in range(protected_length, 16):
        intermediate[i] = previous[i] ^ original_pad

    for pad_value in range(original_pad + 1, 17):
        index = 16 - pad_value
        candidate = bytearray(previous)

        for j in range(index + 1, 16):
            candidate[j] = intermediate[j] ^ pad_value

        recovered = None
        for guess in range(256):
            candidate[index] = guess
            if oracle.query(candidate.hex()):
                recovered = guess ^ pad_value
                break

        if recovered is None:
            raise RuntimeError("oracle recovery failed")
        intermediate[index] = recovered

    padded = bytes(intermediate[i] ^ previous[i] for i in range(16))
    if padded[-original_pad:] != bytes([original_pad]) * original_pad:
        raise RuntimeError("invalid recovered padding")

    plaintext = padded[:protected_length]
    sys.stdout.write(json.dumps({"plaintext_hex": plaintext.hex()}, separators=(",", ":")))


if __name__ == "__main__":
    main()
